import asyncio
files = ["ledger/18.csv","ledger/23.csv","ledger/07.csv","ledger/02.csv","ledger/00.csv","ledger/20.csv","ledger/17.csv","ledger/16.csv","ledger/19.csv","ledger/13.csv","ledger/12.csv","ledger/10.csv","ledger/22.csv","ledger/01.csv","ledger/21.csv","ledger/03.csv","ledger/11.csv","ledger/09.csv","ledger/15.csv","ledger/08.csv","ledger/04.csv","ledger/14.csv","ledger/05.csv","ledger/06.csv"]
texts = {}
for i in range(0, len(files), 6):
    batch = files[i:i+6]
    rs = await asyncio.gather(*[yuki_workspace_read({"path": "/workspace/"+f}) for f in batch])
    for f, r in zip(batch, rs):
        if r['ok']:
            texts[f] = r['data']['text']

recs = {}
total_lines = 0
bad = []
for f in files:
    lines = texts[f].split("\n")
    for ln in lines[1:]:
        ln = ln.strip()
        if not ln:
            continue
        total_lines += 1
        parts = ln.split(",")
        if len(parts) != 4:
            bad.append((f, ln))
            continue
        rid, region, amount, status = parts[0], parts[1], int(parts[2]), parts[3]
        key = rid
        if key in recs:
            if recs[key] != (region, amount, status):
                bad.append(("dupconflict", ln))
        else:
            recs[key] = (region, amount, status)

agg = {}
for region, amount, status in recs.values():
    if status == "void":
        continue
    if status != "ok":
        bad.append(("status", region, amount, status))
        continue
    c, s = agg.get(region, (0, 0))
    agg[region] = (c+1, s+amount)

tsv = "".join(region + "\t" + str(agg[region][0]) + "\t" + str(agg[region][1]) + "\n" for region in ["A","B","C","D"])
res = {"lines": total_lines, "unique_ids": len(recs), "bad": bad, "agg": {k: agg[k] for k in ["A","B","C","D"]}, "tsv": tsv}
res
